<?php
declare(strict_types=1);

function h(string $value): string
{
    return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

$query = $_GET;
$query['combination_detail'] = '1';
$includeFunding = (string) ($query['include_funding'] ?? '1') !== '0';
$slippageBps = (string) ($query['slippage_bps'] ?? '0');
$endpoint = 'portfolio-combination-data.php?' . http_build_query($query);
$martingaleActive = in_array((string) ($query['martingale_mode'] ?? 'none'), ['simple', 'reverse', 'simple_profit', 'reverse_profit'], true);
$comparisonQuery = $query;
$comparisonQuery['martingale_mode'] = 'none';
$comparisonQuery['exit_config'] = preg_replace('/:(scaled|fixed)$/', '', (string) ($comparisonQuery['exit_config'] ?? ''));
$comparisonEndpoint = 'portfolio-combination-data.php?' . http_build_query($comparisonQuery);
$today = new DateTimeImmutable('today', new DateTimeZone('Europe/Kyiv'));
$trainingStart = DateTimeImmutable::createFromFormat('!Y-m-d', (string) ($query['start_day'] ?? '')) ?: $today;
$trainingEnd = DateTimeImmutable::createFromFormat('!Y-m-d', (string) ($query['end_day'] ?? '')) ?: $trainingStart;
$validationStart = $trainingEnd->modify('+1 day');
$trainingDays = max(1, (int) $trainingStart->diff($trainingEnd)->format('%a') + 1);
$validationEnd = $validationStart->modify('+' . ($trainingDays - 1) . ' days');
if ($validationStart <= $today && $validationEnd > $today) $validationEnd = $today;
$validationStartValue = $validationStart->format('Y-m-d');
$validationEndValue = $validationEnd->format('Y-m-d');
$entryLabel = trim((string) ($_GET['entry_label'] ?? $_GET['entry_config'] ?? 'Порог входа'));
$exitLabel = trim((string) ($_GET['exit_label'] ?? $_GET['exit_config'] ?? 'TakeProfit & StopLoss'));
?>
<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Результаты комбинации по тикерам</title>
<style>
:root{color-scheme:dark;--bg:#101723;--panel:#182235;--line:#2c3b55;--text:#e8edf6;--muted:#a4b1c7;--green:#7ee0ad;--red:#ff8e99}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,sans-serif}.wrap{width:min(1500px,calc(100% - 32px));margin:32px auto}.panel{padding:22px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}h1{margin:0 0 18px;font-size:24px}.pair{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px;margin:0 0 18px}.pair div{padding:12px;border:1px solid var(--line);border-radius:10px;overflow-wrap:anywhere}.pair dt{color:var(--muted);font-size:13px}.pair dd{margin:5px 0 0;font-weight:700}.status{margin:0 0 12px;color:var(--muted)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:650px}th,td{padding:11px 13px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.04em}td.numeric{text-align:right;font-variant-numeric:tabular-nums}.positive{color:var(--green)}.negative{color:var(--red)}.no-data{color:var(--muted)}tr:last-child td{border-bottom:0}.back{display:inline-block;margin-bottom:14px;color:#b8c7ff}.page-nav{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 20px;padding:5px;border:1px solid var(--line);border-radius:12px;background:#0c1222;width:max-content;max-width:100%}.page-nav a{color:#b7c1d5;text-decoration:none;padding:9px 14px;border-radius:8px}.page-nav a:hover{background:#1b2843;color:#e9eefb}@media(max-width:600px){.page-nav{width:100%}.page-nav a{flex:1;text-align:center}}.error{color:var(--red)}
</style>
</head>
<body><main class="wrap"><a class="back" href="./">← Назад к рейтингу</a><nav class="page-nav" aria-label="Разделы"><a href="./">Базовые проверки</a><a href="hedging.php">Хеджирование</a><a href="favorites.php">Избранное</a><a href="settings.php">Настройки</a><a href="autotrading.php?mode=paper">Автоторговля (Тест)</a><a href="autotrading.php?mode=real">Автоторговля (реал)</a><a href="autotrading-pi.php">Raspberry Pi</a></nav><section class="panel">
<h1>Итог выбранной комбинации по каждому тикеру</h1>
<dl class="pair"><div><dt>Лучший порог входа</dt><dd><?= h($entryLabel) ?></dd></div><div><dt>TakeProfit &amp; StopLoss</dt><dd><?= h($exitLabel) ?></dd></div></dl>
<p>Период: <?= h((string) ($query['start_day'] ?? '')) ?> — <?= h((string) ($query['end_day'] ?? '')) ?> · стартовый баланс: <?= h((string) ($query['balance'] ?? '10')) ?> USDT · комиссия: <?= h((string) ($query['fee'] ?? '0.06')) ?>% за сторону.</p>
<p class="status">Затраты: funding <?= $includeFunding ? 'включён по историческим ставкам Bitget' : 'отключён' ?> · проскальзывание <?= h($slippageBps) ?> б.п. на каждую сторону. Используются действующие правила количества Bitget; для прошлого нет архива правил контракта. В истории снимков нет mark price, поэтому для funding используется midpoint первой котировки после settlement.</p>
<?php if ($martingaleActive): ?><button id="compare-no-martingale" type="button" data-endpoint="<?= h($comparisonEndpoint) ?>" disabled>Сравнить с вариантом без мартингейла</button><p class="status" id="comparison-status" role="status" aria-live="polite" hidden></p><div class="pair"><label>Проверочный период · с даты<input type="date" id="validation-start" value="<?= h($validationStartValue) ?>"></label><label>Проверочный период · по дату<input type="date" id="validation-end" value="<?= h($validationEndValue) ?>"></label></div><button id="run-out-of-sample" type="button" data-endpoint="<?= h($endpoint) ?>" disabled>Проверить на отложенном периоде</button><p class="status" id="out-of-sample-status" role="status" aria-live="polite" hidden></p><div class="table-wrap" id="out-of-sample-results" hidden><table><thead><tr><th>Тикер</th><th>Обучающий период · PnL</th><th>Отложенный период · PnL</th><th class="numeric">Цепочек</th><th class="numeric">Худшая цепочка</th><th class="numeric">Просадка</th></tr></thead><tbody></tbody></table></div><?php endif; ?>
<p class="status" id="status" role="status" aria-live="polite">Подготавливаю результаты по тикерам…</p>
<div class="table-wrap"><table><thead><tr><th>Тикер</th><th>Порог входа</th><th>TakeProfit &amp; StopLoss</th><th class="numeric">Итог тикера</th><th class="numeric">Ордеров</th><th class="numeric">Цепочек</th><th class="numeric">Худшая цепочка</th><th class="numeric">Просадка</th><th class="numeric comparison-column" hidden>Без мартингейла · итог</th><th class="numeric comparison-column" hidden>Без мартингейла · сделок</th><th class="numeric comparison-column" hidden>Разница</th></tr></thead><tbody id="results"></tbody></table></div>
</section></main>
<script>
const endpoint=<?= json_encode($endpoint, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>;
const statusNode=document.querySelector('#status');
const bodyNode=document.querySelector('#results');
const compareButton=document.querySelector('#compare-no-martingale');
const outOfSampleButton=document.querySelector('#run-out-of-sample');
const moneySigned=value=>{if(value===null||value===undefined)return 'нет надёжных данных';const n=Number(value);return (n>0?'+':'')+n.toFixed(4).replace('.',',')+' USDT'};
const money=value=>{if(value===null||value===undefined)return 'нет надежных данных';const n=Number(value);return (n>0?'+':'')+n.toFixed(4).replace('.',',')+' USDT'};
async function requestReady(url){for(;;){const response=await fetch(url,{headers:{Accept:'application/json'}});const data=await response.json();if(!response.ok||data.status==='error')throw new Error(data.message||'Не удалось получить результаты комбинации');if(data.status==='pending'){await new Promise(resolve=>setTimeout(resolve,1200));continue;}if(data.status!=='ready')throw new Error('Результаты комбинации пока недоступны');return data;}}
async function load(){try{const data=await requestReady(endpoint);bodyNode.replaceChildren(...data.tickers.map(item=>{const row=document.createElement('tr');row.dataset.symbol=item.symbol;row.dataset.pnl=item.pnl===null?'':String(item.pnl);row.dataset.worstChain=item.worst_chain??'';row.dataset.maxDrawdown=item.max_drawdown??'';const values=[item.symbol,data.entry_label,data.exit_label,money(item.pnl),String(item.trade_count),String(item.chain_count??item.trade_count),moneySigned(item.worst_chain),money(item.max_drawdown)];values.forEach((value,index)=>{const cell=document.createElement('td');cell.textContent=value;if(index===3||index===6){cell.className='numeric';const raw=index===3?item.pnl:item.worst_chain;if(raw===null||raw===undefined)cell.classList.add('no-data');else cell.classList.add(Number(raw)>=0?'positive':'negative');}if(index===7||index===4||index===5)cell.className='numeric';row.append(cell);});return row;}));if(compareButton)compareButton.disabled=false;if(outOfSampleButton)outOfSampleButton.disabled=false;statusNode.textContent='Тикеров: '+data.tickers.length+' · минимум независимых выборок для рейтинга: '+data.min_trades+'. Показаны все доступные результаты; без закрытых позиций указано «нет надёжных данных».';}catch(error){statusNode.textContent=error.message;statusNode.classList.add('error');}}
compareButton?.addEventListener('click',async()=>{const comparisonStatus=document.querySelector('#comparison-status');compareButton.disabled=true;comparisonStatus.hidden=false;comparisonStatus.classList.remove('error');comparisonStatus.textContent='Рассчитываю вариант без мартингейла…';try{const data=await requestReady(compareButton.dataset.endpoint);const baselines=new Map(data.tickers.map(item=>[item.symbol,item]));for(const header of document.querySelectorAll('.comparison-column'))header.hidden=false;for(const row of bodyNode.querySelectorAll('tr')){const baseline=baselines.get(row.dataset.symbol);const value=baseline?.pnl??null;const baselineCell=document.createElement('td');baselineCell.className='numeric comparison-column';baselineCell.textContent=moneySigned(value);if(value!==null)baselineCell.classList.add(Number(value)>=0?'positive':'negative');else baselineCell.classList.add('no-data');const countCell=document.createElement('td');countCell.className='numeric comparison-column';countCell.textContent=String(baseline?.trade_count??0);const current=row.dataset.pnl===''?null:Number(row.dataset.pnl);const deltaCell=document.createElement('td');deltaCell.className='numeric comparison-column';if(value!==null&&current!==null&&Number.isFinite(current)){const delta=current-Number(value);deltaCell.textContent=moneySigned(delta);deltaCell.classList.add(delta>=0?'positive':'negative');}else{deltaCell.textContent='—';deltaCell.classList.add('no-data');}row.append(baselineCell,countCell,deltaCell);}comparisonStatus.textContent='Сравнение рассчитано на тех же датах, тикерах, сигнале, TP/SL, стартовом балансе и комиссии. Разница = мартингейл минус вариант без мартингейла.';}catch(error){comparisonStatus.textContent=error.message;comparisonStatus.classList.add('error');compareButton.disabled=false;}});
outOfSampleButton?.addEventListener('click',async()=>{const status=document.querySelector('#out-of-sample-status');const results=document.querySelector('#out-of-sample-results');const resultBody=results.querySelector('tbody');const startInput=document.querySelector('#validation-start');const endInput=document.querySelector('#validation-end');const training=new URL(endpoint,location.href);const trainingStart=training.searchParams.get('start_day')||'';const trainingEnd=training.searchParams.get('end_day')||'';const validationStart=startInput.value;const validationEnd=endInput.value;status.hidden=false;status.classList.remove('error');if(!validationStart||!validationEnd||validationStart<=trainingEnd||validationEnd<validationStart){status.textContent='Период проверки должен идти после обучающего периода и иметь корректные даты.';status.classList.add('error');return;}outOfSampleButton.disabled=true;results.hidden=true;status.textContent='Рассчитываю выбранные настройки на отложенном периоде…';try{const validationUrl=new URL(outOfSampleButton.dataset.endpoint,location.href);validationUrl.searchParams.set('start_day',validationStart);validationUrl.searchParams.set('end_day',validationEnd);const data=await requestReady(validationUrl.toString());const outOfSample=new Map(data.tickers.map(item=>[item.symbol,item]));resultBody.replaceChildren(...Array.from(bodyNode.querySelectorAll('tr')).map(trainingRow=>{const result=outOfSample.get(trainingRow.dataset.symbol);const validationPnl=result?.pnl??null;const cells=[trainingRow.dataset.symbol,moneySigned(trainingRow.dataset.pnl===''?null:Number(trainingRow.dataset.pnl)),moneySigned(validationPnl),String(result?.chain_count??0),moneySigned(result?.worst_chain),money(result?.max_drawdown)];return cells.map((value,index)=>{const cell=document.createElement('td');cell.textContent=value;if(index===1||index===2||index===4){cell.className='numeric';const raw=index===1?(trainingRow.dataset.pnl===''?null:Number(trainingRow.dataset.pnl)):(index===2?validationPnl:result?.worst_chain);if(raw===null||raw===undefined)cell.classList.add('no-data');else cell.classList.add(Number(raw)>=0?'positive':'negative');}if(index===3||index===5)cell.className='numeric';return cell;}).reduce((row,cell)=>{row.append(cell);return row;},document.createElement('tr'));}));results.hidden=false;status.textContent='Обучающий период: '+trainingStart+' — '+trainingEnd+'. Отложенная проверка: '+validationStart+' — '+validationEnd+'. Параметры входа/выхода и затраты сохранены; настройки не подбирались на проверочном периоде.';outOfSampleButton.disabled=false;}catch(error){status.textContent=error.message;status.classList.add('error');outOfSampleButton.disabled=false;}});
document.querySelectorAll('#validation-start,#validation-end').forEach(input=>input.addEventListener('change',()=>{if(outOfSampleButton)outOfSampleButton.disabled=false;}));
load();
</script>
</body></html>
